<script setup lang="ts">import {onMounted,ref} from 'vue';import {RouterLink} from 'vue-router';import {idr} from '../api';import {useCart,useSession} from '../stores';const cart=useCart(),session=useSession(),error=ref('');onMounted(async()=>{if(session.user)try{await cart.load()}catch(e:any){error.value=e.message}});async function change(id:string,q:number){try{await cart.quantity(id,q)}catch(e:any){error.value=e.message}}</script>
<template><main class="container page"><header class="page-title"><small>YOUR BAG</small><h1>Ready when you are.</h1></header><p v-if="error" class="notice">{{error}}</p><div v-if="!session.user" class="empty">Please <RouterLink to="/login">sign in</RouterLink> to view your bag.</div><div v-else-if="!cart.cart?.items.length" class="empty">Your bag is waiting for something special.<br/><RouterLink class="button" to="/products">Discover collection</RouterLink></div><section v-else class="cart-layout"><div class="cart-items"><article v-for="item in cart.cart?.items" :key="item.id"><img :src="item.product.images[0]?.imageUrl"/><div><small>{{item.product.category.name}}</small><h3>{{item.product.name}}</h3><b>{{idr(item.product.price)}}</b><div class="stepper"><button @click="change(item.id,item.quantity-1)" :disabled="item.quantity===1">−</button><span>{{item.quantity}}</span><button @click="change(item.id,item.quantity+1)">+</button><button class="remove" @click="cart.remove(item.id)">Remove</button></div></div><b>{{idr(Number(item.product.price)*item.quantity)}}</b></article></div><aside class="summary"><h2>Order summary</h2><p><span>Subtotal</span><b>{{idr(cart.total)}}</b></p><p><span>Shipping</span><span>Calculated at checkout</span></p><hr/><p class="total"><span>Subtotal</span><b>{{idr(cart.total)}}</b></p><RouterLink class="button" to="/checkout">Proceed to checkout</RouterLink></aside></section></main></template>
